param([Parameter(Mandatory=$true)][ValidateSet('Debug','Release')][string]$Configuration,[switch]$ExecutionAuthorized)
# One fresh r3 call after the audited incomplete r2; retained r2 program, no rebuild or old output reuse.
$ErrorActionPreference='Stop';$Configuration=if($Configuration -ieq 'Debug'){'Debug'}else{'Release'}
$tests=Split-Path -Parent $PSScriptRoot;$case=Split-Path -Parent $tests;$tag='upl_cryer_gpu_component_'+$Configuration+'_probe_r3'
$startPath=Join-Path $tests ('logs\'+$tag+'.start.json');$record=Join-Path $tests ('logs\'+$tag+'.run.json');$callPath=Join-Path $tests ('logs\'+$tag+'.call.json');$log=Join-Path $tests ('logs\'+$tag+'.log');$out=Join-Path $tests ('outputs\'+$tag);$cache=@{}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function RawE([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p)) -Force;Need (!$f.PSIsContainer) 'Expected bound file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function E([string]$p){$key=([IO.Path]::GetFullPath($p)).ToLowerInvariant();if(!$cache.ContainsKey($key)){$cache[$key]=RawE $p};return $cache[$key]}
function V($rows){foreach($e in @($rows)){Need ($e.path -and $null -ne $e.bytes -and $e.sha256 -match '^[0-9a-fA-F]{64}$') 'Malformed bound Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed/conflicting bound Entry: '+$e.path)}}
function FinalV($rows){$seen=@{};foreach($e in @($rows)){$key=([IO.Path]::GetFullPath($e.path)).ToLowerInvariant();if(!$seen.ContainsKey($key)){$seen[$key]=RawE $e.path};$a=$seen[$key];Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Final changed/conflicting Entry: '+$e.path)}}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in @($paths)){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 16)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){Need ($null -ne $v) 'Missing numeric field';if($v -is [ValueType]){$x=[double]$v}else{$x=0.;Need (![string]::IsNullOrWhiteSpace([string]$v) -and [double]::TryParse([string]$v,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$x)) ('Nonnumeric CSV field: '+[string]$v)};Need (![double]::IsNaN($x) -and ![double]::IsInfinity($x)) 'Nonfinite numeric field';return $x}
function Count($v){Need (($v -is [int] -or $v -is [long]) -and $v -ge 0) 'Expected nonnegative JSON integer edge count';return $v}
function PassedCall($e){V @($e);$c=J $e.path;Need ($c.direct_native_call -and $c.typed_LASTEXITCODE_captured_immediately -and $c.owned_call_exited -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Actual owned direct typed exit0 required';V @($c.program,$c.log);return $c}
Need $ExecutionAuthorized.IsPresent 'Root full read and explicit component execution authorization required';Fresh @($startPath,$record,$callPath,$log,$out,(Join-Path $tests ('logs\'+$tag+'_review_r3.check.json')))
$auditE=E (Join-Path ((Get-Item -LiteralPath $tests).Parent.Parent.FullName) '02_TerzaghiConsolidation_q0_PR\tests\logs\upl_mid_gpu_interruption_r1.check.json')
Need ($auditE.bytes -eq 1200299 -and $auditE.sha256 -ceq '15c9b4fb9e23f8e89c540db9ccf2aadb0b68ff48934109613bf63f86716c8160') 'Exact retained interruption audit required'
$audit=J $auditE.path
Need ($audit.stage -ceq 'upl_mid_gpu_interruption_r1' -and $audit.interruption_audited -eq $true -and $audit.all_observed_owned_processes_absent -eq $true -and $null -eq $audit.real_exit_code -and $audit.typed_exit_evidence_available -eq $false -and $audit.normal_completion_or_failure_exit_invented -eq $false -and $audit.old_full_gate_preserved -eq $true -and $audit.physical_acceptance -eq $false -and $audit.GPU.tag -ceq 'upl_cryer_gpu_component_Debug_probe_r2' -and $audit.GPU.completed_six_probes -eq $false -and $null -eq $audit.GPU.real_tool_exit -and $audit.GPU.memcheck_pass_claimed -eq $false) 'Incomplete r2 must not be adopted as a passing native call'
$helperE=E (Join-Path $tests ('logs\upl_cryer_gpu_component_'+$Configuration+'_r2.helper.json'));$h=J $helperE.path
Need ($h.passed -and $h.stage -ceq 'upl_cryer_gpu_component_build_r2' -and $h.status -ceq 'frozen_cryer_GPU_component_linked_not_run' -and $h.kind -ceq 'component' -and $h.configuration -ceq $Configuration -and $h.frozen_build_program_inputs_runtime_unchanged -and $h.actual_headers_archived_not_live -and $h.exact_link_closure_verified -and !$h.program_run -and !$h.production_build_executed -and $h.GPU_non_main_objects -eq 110 -and $h.link_object_count -eq 111 -and @($h.objects).Count -eq 110 -and @($h.retained_build_objects111).Count -eq 111 -and @($h.source_snapshots265).Count -eq 265 -and @($h.actual_project_headers).Count -gt 0 -and @($h.libraries).Count -eq 18 -and @($h.runtime).Count -eq 4) 'Passed selected archived GPU110+1 r2 component helper required'
Need ([IO.Path]::GetFileName($h.program.path) -ceq 'upl_cryer_gpu_component_r2.exe') 'Only the sealed component program is allowed'
if($Configuration -ceq 'Debug'){Need ($audit.GPU.helper.path -ieq $helperE.path -and $audit.GPU.helper.bytes -eq $helperE.bytes -and $audit.GPU.helper.sha256 -ceq $helperE.sha256) 'Debug must reuse exactly the audited completed r2 helper build'}
$own=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_run_r3.json')),(E (Join-Path $PSScriptRoot 'upl_cryer_gpu_component_r2.cpp')),(E (Join-Path $tests 'notes\upl_cryer_gpu_component_r2.json')))
$declared=J (Join-Path $tests 'notes\upl_cryer_gpu_component_r2.json');$p=$declared.retained_input_provenance
$runtime=E (Join-Path $case $p.runtime);$seed=E (Join-Path $case $p.seed)
Need ($runtime.bytes -eq $p.runtime_bytes -and $runtime.sha256 -ceq $p.runtime_sha256 -and $seed.bytes -eq $p.seed_bytes -and $seed.sha256 -ceq $p.seed_sha256 -and [IO.Path]::ChangeExtension($runtime.path,'.bi4') -ieq $seed.path) 'Exact retained nu.3 runtime and initial BI4 required'
$bindings=@($auditE,$helperE,$h.program,$h.source_build,$h.retained_compiler_recipe,$h.compiler_dependency_record,$h.helper_object,$h.compile_call,$h.link_call,$h.documentation_snapshot,$h.case_readme_snapshot,$runtime,$seed)+$own+@($h.inputs)+@($h.author_files)+@($h.source_snapshots265)+@($h.actual_project_headers)+@($h.objects)+@($h.retained_build_objects111)+@($h.libraries)+@($h.tools)
foreach($pair in $h.runtime){Need ($pair.original.bytes -eq $pair.copy.bytes -and $pair.original.sha256 -ieq $pair.copy.sha256) 'Recorded runtime-copy identity differs';$bindings+=@($pair.copy)} # Rehash own copies, not original/canonical runtime paths.
V $bindings;[void](PassedCall $h.compile_call);[void](PassedCall $h.link_call)
$debugReceipt=$null
if($Configuration -ceq 'Release'){
  $debugReceipt=E (Join-Path $tests 'logs\upl_cryer_gpu_component_Debug_probe_r3_review_r3.check.json');$d=J $debugReceipt.path
  Need ($d.passed -and $d.stage -ceq 'upl_cryer_gpu_component_review_r3' -and $d.configuration -ceq 'Debug' -and $d.typed_owned_tool_exit0 -and $d.memcheck_errors -eq 0 -and $d.initialization_metadata_only -and $d.no_particle_snapshots_or_exclusions -and $d.component_completion_verified -and $d.physical_acceptance -eq $false) 'Actual Debug memcheck and strict offline review required'
  V (@($debugReceipt,$d.source_run,$d.source_call,$d.helper,$d.completion)+@($d.inputs)+@($d.files))
}
$targetArgv=@('--input',$runtime.path,'--out',$out);$memlog=Join-Path $tests ('logs\'+$tag+'.memcheck.log');$tool=$h.program;$argv=$targetArgv
if($Configuration -ceq 'Debug'){
  Fresh @($memlog);$tool=E 'C:\Program Files\NVIDIA GPU Computing Toolkit\CUDA\v11.7\compute-sanitizer\compute-sanitizer.exe'
  $argv=@('--tool','memcheck','--leak-check','full','--error-exitcode','99','--log-file',$memlog,$h.program.path)+$targetArgv
}
$active=@(Get-CimInstance Win32_Process -Filter "Name LIKE 'DualSPHysics%.exe' OR Name LIKE 'upl_%.exe' OR Name = 'compute-sanitizer.exe'")
Need ($active.Count -eq 0) 'Another project process is active; no duplicate component or solver'
$ownerProcess=Get-CimInstance Win32_Process -Filter ('ProcessId = '+$PID)
Need ($null -ne $ownerProcess) 'Actual owner process identity unavailable'
Save $startPath ([ordered]@{stage='upl_cryer_gpu_component_start_r3';configuration=$Configuration;started_utc=[DateTime]::UtcNow.ToString('o');owner_pid=$PID;owner_parent_pid=$ownerProcess.ParentProcessId;owner_creation_utc=$ownerProcess.CreationDate.ToUniversalTime().ToString('o');owner_script=(E $PSCommandPath);interruption_audit=$auditE;helper=$helperE;program=$h.program;fresh_attempt_after_incomplete_r2=$true;old_r2_exit_reconstructed=$false;prior_native_completion_adopted=$false;native_call_started_by_start_record=$false;physical_acceptance=$false})
$startE=E $startPath
$inputEntries=@($cache.Values|Sort-Object path);$working=Split-Path -Parent $h.program.path
[IO.File]::WriteAllBytes($log,[byte[]]@());$code=$null;$invokeFailure=$null;$priorityDuring=$null;$started=[DateTime]::UtcNow.ToString('o');$prior=$ErrorActionPreference;$launcher=[Diagnostics.Process]::GetCurrentProcess();$oldPriority=$launcher.PriorityClass
Push-Location $working
try{$launcher.PriorityClass=[Diagnostics.ProcessPriorityClass]::BelowNormal;$priorityDuring=[string]$launcher.PriorityClass;$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $tool.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$invokeFailure=$_.Exception.Message}finally{Pop-Location;$ErrorActionPreference=$prior;try{$launcher.PriorityClass=$oldPriority}catch{if(!$invokeFailure){$invokeFailure='Launcher priority restore failed: '+$_.Exception.Message}}}
# Seal the real native call before any completion/CSV analysis. A later checker failure never authorizes another call.
Save $callPath ([ordered]@{program=$tool;target_program=$h.program;arguments=$argv;target_arguments=$targetArgv;working_directory=$working;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$invokeFailure;log=(E $log);launcher_priority_during_call=$priorityDuring;child_priority_independently_observed=$false;component_call=$true;actual_solver_call=$false;sanitizer_used=($Configuration -ceq 'Debug');target_exit_independently_captured=($Configuration -ceq 'Release');requested_OpenMP_threads=1;physical_acceptance=$false})
$callE=E $callPath;$callOK=($code -is [int] -and $code -eq 0 -and !$invokeFailure);$postBindingFailure=$null;$analysisFailure=$null;$unchanged=$false;$verified=$false;$completion=$null
try{FinalV $inputEntries;$unchanged=$true}catch{$postBindingFailure=$_.Exception.Message}
if($callOK){try{
  $completion=E (Join-Path $out 'completion.json');$done=J $completion.path
  Need ($done.passed -and $done.stage -ceq 'upl_cryer_gpu_component_r2' -and $done.native_count -eq 37173 -and $done.fixed_dummy_count -eq 8 -and $done.total_native_count -eq 37181 -and $done.actual_force_calls -eq 6 -and $done.complete_rate_calls_from_force -eq 6 -and $done.explicit_complete_rate_calls -eq 0 -and $done.soil_reference_checks -eq 223038 -and $done.sample_rows -eq 48 -and $done.summary_rows -eq 6 -and $done.actual_physical_steps -eq 0 -and (N $done.actual_time_s) -eq 0 -and $done.feedback_Init_guard_bypassed_by_fixture -eq $true -and $done.observer_Init_guard_bypassed_by_fixture -eq $true -and $done.observer_initialization_validated -eq $false -and $done.feedback_initialization_validated -eq $false -and $done.legacy_GPU_initialization_validated -eq $true -and $done.manual_J1_theta0_installed -eq $true -and $done.manual_J_pool_added8B -eq 4 -and $done.manual_validity_pool_added4B -eq 2 -and $done.public_3D_admitted -eq $false -and $done.physical_acceptance -eq $false -and $done.whole_object_restored -eq $false -and $done.declared_input_bytes_restored -eq $true -and $done.no_Run_ComputeStep_SaveData_restart -eq $true -and $done.raw_LoadAce_gate_accounted -eq $true -and $done.packed_and_double_support_intervals_unambiguous -eq $false -and $done.upper_support_edges_enclosed -eq $true -and $done.zero_distance_ambiguity_rejected -eq $true -and (Count $done.packed_support_edge_pair_count) -gt 0 -and (Count $done.double_support_edge_pair_count) -ge 0 -and (Count $done.theta_inner_support_edge_pair_count) -ge 0 -and (N $done.kernel_edge_grad_bound_max) -gt 0 -and $done.CUDA11p7_published_not_guaranteed_math_envelope_assumed -eq $true) 'Bounded zero-step r2 completion differs'
  $verified=$true
}catch{$analysisFailure=$_.Exception.Message}}
$files=@();if(Test-Path -LiteralPath $out){$files=@(Get-ChildItem -LiteralPath $out -Recurse -File|Sort-Object FullName|ForEach-Object{E $_.FullName})}
$memEntry=$null;if(Test-Path -LiteralPath $memlog){$memEntry=E $memlog}
$passed=($callOK -and $unchanged -and $verified -and !$analysisFailure)
Save $record ([ordered]@{stage='upl_cryer_gpu_component_run_r3';passed=[bool]$passed;configuration=$Configuration;kind='non_advancing_private_GPU3D_component';helper=$helperE;source_build=$h.source_build;program=$h.program;interruption_audit=$auditE;owner_start=$startE;fresh_attempt_after_incomplete_r2=$true;old_r2_exit_reconstructed=$false;call=$callE;arguments=$argv;debug_review=$debugReceipt;inputs=$inputEntries;files=$files;completion=$completion;typed_owned_tool_exit0=[bool]$callOK;component_target_exit_independently_captured=($Configuration -ceq 'Release');memcheck_log=$memEntry;basic_completion_verified=$verified;deep_component_review_completed=$false;component_call_failure=$(if($invokeFailure){$invokeFailure}elseif(!$callOK){'Owned component did not return typed int exit0'}else{$null});basic_analysis_failure=$analysisFailure;post_binding_failure=$postBindingFailure;frozen_build_program_inputs_runtime_unchanged=$unchanged;independent_final_rehash_performed=$true;live_production_sources_frozen_by_this_run=$false;canonical_programs_rechecked=$false;caller_reconstructed_device_or_neighbor_proof=$false;observer_initialization_validated=$false;feedback_initialization_validated=$false;public_3D_admitted=$false;physical_acceptance=$false;CPU_GPU_or_Debug_Release_0ULP_compared=$false;solver_trajectory_started=$false;automatic_follow_up=$false})
if(!$passed){throw ('Component/basic seal failed; preserve all artifacts, no automatic rerun: '+$record)};Write-Output ('GPU component basic call sealed; independent offline review still required: '+$record)
